nodes.id:
external::list.map((item: DecryptedItem & { payload: ExpensePayload }) => {
      if (item.payload.entryType === 'credit') {
        runningBalance += item.payload.amount;
      } else {
        runningBalance -= item.payload.amount;
      }
      return { ...item, balance: runningBalance };
    }).reverse

